def vowel_back(s):
    vowels = "aeiou"
    exceptions = {
        'c': -1,
        'o': -1,
        'd': -3,
        'e': -4
    }

    result = []

    for char in s:
        if char in exceptions:
            shift = exceptions[char]
        elif char in vowels:
            shift = -5
        else:
            shift = 9

        # Calculate new position
        original_pos = ord(char) - ord('a')
        new_pos = (original_pos + shift) % 26
        new_char = chr(new_pos + ord('a'))

        # Check if the new character is one of the exception targets
        if new_char in ['c', 'o', 'd', 'e']:
            result.append(char)
        else:
            result.append(new_char)

    return "".join(result)
